def parse_range(s):
    s = s.strip()
    if s.isdigit():
        return [int(s)]
    if '-' in s:
        parts = s.split('-')
        if len(parts) == 2:
            a, b = parts
            if a.isdigit() and b.isdigit():
                start, end = int(a), int(b)
                if start <= end:
                    return list(range(start, end + 1))
        raise ValueError("Invalid range format: {}".format(s))
    raise ValueError("Invalid range format: {}".format(s))
