def parse_range(s):
    s = s.strip()
    if s.isdigit():
        n = int(s)
        return [n]
    if '-' in s:
        parts = s.split('-')
        if len(parts) != 2:
            raise ValueError("Invalid range format")
        try:
            start, end = parts[0].strip(), parts[1].strip()
            start, end = int(start), int(end)
        except ValueError:
            raise ValueError("Invalid range format")
        if start > end:
            raise ValueError("Invalid range: start > end")
        return list(range(start, end + 1))
    raise ValueError("Invalid range format")
